Backfill script for people who are no longer synced to assembled (but were synced before, and thus can have their last state “hanging”, which would lead to a problem if such person sync re-activated):

{noformat}    async function getPeopleBatch(ctx: Context, offset: number) {
        const resp = await client.getPeople(ctx, {offset, limit: 100});
        await sleep(500); // rate limits
        return Object.values(resp.people ?? {});
    }

    async function iterateOverPeopleWithEndDate(
        ctx: Context,
        callback: (person: AssembledPerson) => Promise<void>,
    ): Promise<void> {
        let countSoFar = 0;
        let batch = await getPeopleBatch(ctx, countSoFar);
        while (batch.length > 0) {
            for (const person of batch) {
                if (!person.end_date) {
                    continue;
                }
                await callback(person);
            }
            countSoFar += batch.length;
            console.log(`Processed ${countSoFar} records by now, proceeding..`);
            batch = await getPeopleBatch(ctx, countSoFar);
        }
        console.log(`Processing finished - ${countSoFar} records total`);
    }

    ctest("do the thing", async (ctx) => {
        const headers = {
            "Accept": "application/json",
            "Content-Type": "application/json",
            "Authorization": "Basic " + Buffer.from(`${API_KEY}:`, "utf-8").toString("base64"),
        };
        const stateUrlBase = "https://api.assembledhq.com/v0/agents/state";
        const nowTs = toUnixTimestamp(new Date());

        const allEdits = [];

        await iterateOverPeopleWithEndDate(ctx, async (person) => {
            const stateResp = await fetch(
                `${stateUrlBase}?agent_id=${person.agent_id!}&start_time=${person.end_date!}&end_time=${nowTs}&limit=1`,
                {headers},
            );

            const lastState = (await stateResp.json())["agent_states"][0];
            if (!lastState) {
                return;
            }

            if (lastState.state.toLowerCase() === "offline" || lastState.end_time <= person.end_date!) {
                return;
            }

            const editPayload = {
                agent_platform_id: person.imported_id,
                platform: "api",
                action: "update",
                data: {
                    id: lastState.external_id,
                    state: lastState.state.toLowerCase(),
                    start_time: lastState.start_time,
                    end_time: person.end_date,
                },
            };
            allEdits.push(editPayload);

            const editRequest = {
                edits: [editPayload],
            };
            console.log(`last state for ${person.imported_id} with end_date ${person.end_date} is`, lastState);
            console.log("edit request is", JSON.stringify(editRequest, null, 4));

            const editResponse = await fetch(`${stateUrlBase}/edit`, {
                headers,
                method: "POST",
                body: JSON.stringify(editRequest),
            });

            if (!editResponse.ok) {
                console.log("edit response is", await editResponse.text());
                throw new Error(`edit failed: ${editResponse.statusText}`);
            }
        });

        console.log("total edit requests length is", allEdits.length);{noformat}


